#endif

    if !options.args.isEmpty {
      traverse(options.args, options.fts_options);
    }
    else {
      traverse(["."], options.fts_options);
    }

    // FIXME: how to detect error
    if r.rval == 0 && (ferror(stdout) != 0 || fflush(stdout) != 0) {
      err(1, "stdout");
    }

    exit(Int32(r.rval))
  }

